class InAppNotification extends HTMLElement {
  /** @type {InAppNotificationContainer} */
  #container = null;

  /** @type {Notification} */
  #data = null;

const attributes = {
  CTA: "cta",
  description: "description",
  id: "data-id",
  title: "heading",
  type: "type",
  URL: "url",
};

for (const [key, value] of Object.entries(attributes)) {
  this.#container.setAttribute(value, notification[key]);
}
